create table public.repositories (id uuid primary key default gen_random_uuid(), project_id uuid not null unique references public.projects(id) on delete cascade, provider text not null check (provider in ('github', 'gitlab', 'bitbucket')), repository_url text not null, repository_name text not null, owner text not null, default_branch text not null, access_type text not null default 'public' check (access_type in ('public', 'private')), external_repository_id text not null, credential_reference text, connected_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.repository_analyses (id uuid primary key default gen_random_uuid(), repository_id uuid not null references public.repositories(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, commit_sha text not null default '', status text not null check (status in ('queued', 'running', 'completed', 'failed')), frameworks jsonb not null default '{}'::jsonb, languages jsonb not null default '{}'::jsonb, dependencies jsonb not null default '{}'::jsonb, infrastructure jsonb not null default '{}'::jsonb, architecture jsonb not null default '{}'::jsonb, metrics jsonb not null default '{}'::jsonb, analysis_data jsonb not null default '{}'::jsonb, started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now());
create table public.dependencies (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, repository_analysis_id uuid not null references public.repository_analyses(id) on delete cascade, name text not null, version text not null, ecosystem text not null, type text not null check (type in ('runtime', 'development', 'peer', 'infrastructure')), risk_level text not null check (risk_level in ('low', 'medium', 'high', 'critical')), metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique(project_id, name, ecosystem));
create table public.drift_analyses (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, architecture_version_id uuid not null references public.architecture_versions(id), repository_analysis_id uuid not null references public.repository_analyses(id), match_score numeric(5,2) not null check (match_score >= 0 and match_score <= 100), summary text not null, status text not null check (status in ('queued', 'running', 'completed', 'failed')), created_at timestamptz not null default now());
create table public.drift_items (id uuid primary key default gen_random_uuid(), drift_analysis_id uuid not null references public.drift_analyses(id) on delete cascade, type text not null check (type in ('missing', 'extra', 'mismatch')), severity text not null check (severity in ('low', 'medium', 'high', 'critical')), expected jsonb not null default '{}'::jsonb, actual jsonb not null default '{}'::jsonb, description text not null, recommendation text not null, metadata jsonb not null default '{}'::jsonb);
create index repository_analyses_project_idx on public.repository_analyses(project_id, created_at desc); create index dependencies_project_filter_idx on public.dependencies(project_id, type, risk_level, ecosystem); create index drift_analyses_project_idx on public.drift_analyses(project_id, created_at desc); create index drift_items_analysis_idx on public.drift_items(drift_analysis_id);
create trigger repositories_updated_at before update on public.repositories for each row execute function public.set_updated_at();
alter table public.repositories enable row level security; alter table public.repository_analyses enable row level security; alter table public.dependencies enable row level security; alter table public.drift_analyses enable row level security; alter table public.drift_items enable row level security;
create policy repositories_access on public.repositories for select using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))); create policy repositories_manage on public.repositories for all using (public.is_workspace_admin((select workspace_id from public.projects where id = project_id))) with check (public.is_workspace_admin((select workspace_id from public.projects where id = project_id)));
create policy analyses_access on public.repository_analyses for select using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))); create policy analyses_manage on public.repository_analyses for all using (public.is_workspace_admin((select workspace_id from public.projects where id = project_id)));
create policy dependencies_access on public.dependencies for select using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))); create policy drift_access on public.drift_analyses for select using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))); create policy drift_items_access on public.drift_items for select using (public.is_workspace_member((select p.workspace_id from public.projects p join public.drift_analyses d on d.project_id = p.id where d.id = drift_analysis_id)));
alter publication supabase_realtime add table public.repository_analyses, public.drift_analyses;